mapper.select:
SELECT w.*, m.name as memberName, c.name as courseName, c.start_time as courseStartTime, co.name as coachName
FROM course_waitlist w
LEFT JOIN member m ON w.member_id = m.id
LEFT JOIN course c ON w.course_id = c.id
LEFT JOIN coach co ON c.coach_id = co.id


        AND w.member_id = #{memberId}


        AND w.course_id = #{courseId}


        AND w.status = #{status}


ORDER BY w.create_time DESC

SELECT COALESCE(MAX(queue_no), 0)
FROM course_waitlist
WHERE course_id = #{courseId}

SELECT w.*, m.name as memberName, m.phone as memberPhone
FROM course_waitlist w
LEFT JOIN member m ON w.member_id = m.id
WHERE w.course_id = #{courseId}

    AND w.status = #{status}

ORDER BY w.queue_no ASC
